/**
 * CPython-compatible standard stream emulation.
 *
 * CPython buffers `sys.stdout` differently depending on whether it is attached
 * to a terminal:
 *   - TTY   -> line buffered (each `print()` reaches the terminal immediately)
 *   - pipe  -> block buffered (everything is flushed when the process exits)
 * `sys.stderr` is always write-through, so when stdout is redirected to a pipe
 * a traceback shows up *before* any previously printed stdout text.
 *
 * Reproducing that ordering matters for byte-for-byte comparison of a combined
 * `2>&1` capture, so stdout is accumulated here and flushed on exit.
 */

import { writeSync } from 'node:fs';

const STDOUT_FD = 1;
const STDERR_FD = 2;

const pending = [];
const lineBuffered = process.stdout.isTTY === true;

/** Write a string to a file descriptor, looping over partial/blocked writes. */
function rawWrite(fd, text) {
  if (text === '') return;
  const buf = Buffer.from(text, 'utf8');
  let offset = 0;
  while (offset < buf.length) {
    try {
      offset += writeSync(fd, buf, offset, buf.length - offset);
    } catch (err) {
      if (err.code === 'EAGAIN') continue; // non-blocking pipe: retry
      if (err.code === 'EPIPE') return; // reader went away
      throw err;
    }
  }
}

/** Equivalent of `sys.stdout.write(text)`. */
export function stdoutWrite(text) {
  if (lineBuffered) rawWrite(STDOUT_FD, text);
  else pending.push(text);
}

/** Equivalent of `sys.stderr.write(text)` (never buffered). */
export function stderrWrite(text) {
  rawWrite(STDERR_FD, text);
}

/** Equivalent of `sys.stdout.flush()`. */
export function flushStdout() {
  if (pending.length === 0) return;
  const text = pending.join('');
  pending.length = 0;
  rawWrite(STDOUT_FD, text);
}

/** Equivalent of `print(text)` — a single object followed by a newline. */
export function pyPrint(text) {
  stdoutWrite(`${text}\n`);
}

/** Flush buffered stdout and terminate, like CPython's interpreter shutdown. */
export function pyExit(code) {
  flushStdout();
  process.exit(code);
}

