/**
 * Python `repr()` / `str()` for the value kinds this program handles:
 * `str` (command line keys) and `int` (arbitrary precision, held as BigInt).
 */

// A code point is unprintable when its Unicode category is C* or Z* — except
// for U+0020, which Python considers printable. Mirrors `str.isprintable()`.
const UNPRINTABLE = /^[\p{C}\p{Z}]$/u;

function isPrintable(codePoint) {
  if (codePoint === 0x20) return true;
  if (codePoint < 0x7f) return codePoint >= 0x21;
  if (codePoint === 0x7f) return false;
  return !UNPRINTABLE.test(String.fromCodePoint(codePoint));
}

function escapeCodePoint(codePoint) {
  if (codePoint < 0x100) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint < 0x10000) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

/**
 * `repr()` of a Python `str`: single quotes by default, double quotes when the
 * value contains a single quote but no double quote.
 */
export function reprStr(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of value) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += `\\${ch}`;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (isPrintable(cp)) out += ch;
    else out += escapeCodePoint(cp);
  }
  return out + quote;
}

/** `repr()` of a Python `int`. */
export function reprInt(value) {
  return value.toString();
}

/** `repr()` dispatcher for the types used here. */
export function pyRepr(value) {
  if (typeof value === 'string') return reprStr(value);
  if (typeof value === 'bigint') return reprInt(value);
  if (value === null) return 'None';
  return String(value);
}

/** `str()` dispatcher — strings render bare, everything else like `repr()`. */
export function pyStr(value) {
  return typeof value === 'string' ? value : pyRepr(value);
}

/** `repr()` of a tuple, including the trailing comma of 1-tuples. */
export function reprTuple(items) {
  if (items.length === 0) return '()';
  if (items.length === 1) return `(${pyRepr(items[0])},)`;
  return `(${items.map(pyRepr).join(', ')})`;
}

/** `repr()` of a dict built from ordered `[key, value]` pairs. */
export function reprDict(entries) {
  const body = entries.map(([k, v]) => `${pyRepr(k)}: ${pyRepr(v)}`).join(', ');
  return `{${body}}`;
}

