/**
 * Python `int(str)` semantics, including the details argparse exposes through
 * `type=int`:
 *   - surrounding Unicode whitespace is stripped
 *   - an optional leading `+` / `-` sign
 *   - `_` may separate digit groups (never leading, trailing, or doubled)
 *   - any Unicode decimal digit (category Nd) counts, not just ASCII 0-9
 *   - the result has arbitrary precision, so it is returned as a BigInt
 */

// Characters for which Python's `str.isspace()` is true.
const PY_SPACE =
  '[\\t\\n\\v\\f\\r \\x1c-\\x1f\\x85\\u00a0\\u1680\\u2000-\\u200a' +
  '\\u2028\\u2029\\u202f\\u205f\\u3000]';
const STRIP_RE = new RegExp(`^${PY_SPACE}+|${PY_SPACE}+$`, 'g');
const DECIMAL_DIGIT = /^\p{Nd}$/u;

/** Thrown where CPython raises `ValueError` from `int()`. */
export class PyValueError extends Error {}

function isDecimalDigit(ch) {
  return DECIMAL_DIGIT.test(ch);
}

/**
 * Numeric value 0-9 of a Unicode decimal digit. Each Nd set occupies ten
 * consecutive code points, so the offset from the set's zero is the value.
 */
function digitValue(ch) {
  const cp = ch.codePointAt(0);
  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30;
  for (let offset = 0; offset <= 9; offset += 1) {
    const zero = cp - offset;
    if (!isDecimalDigit(String.fromCodePoint(zero))) break;
    if (!isDecimalDigit(String.fromCodePoint(zero - 1))) return offset;
  }
  throw new PyValueError('not a decimal digit');
}

/** Parse `text` the way CPython's `int()` builtin does; returns a BigInt. */
export function pyInt(text) {
  const body = text.replace(STRIP_RE, '');
  const chars = Array.from(body);
  let i = 0;
  let negative = false;
  if (chars[i] === '+' || chars[i] === '-') {
    negative = chars[i] === '-';
    i += 1;
  }
  if (i >= chars.length) throw new PyValueError('no digits');

  let digits = '';
  let previousWasDigit = false;
  for (; i < chars.length; i += 1) {
    const ch = chars[i];
    if (ch === '_') {
      if (!previousWasDigit) throw new PyValueError('misplaced underscore');
      previousWasDigit = false;
      continue;
    }
    if (!isDecimalDigit(ch)) throw new PyValueError('invalid digit');
    digits += String(digitValue(ch));
    previousWasDigit = true;
  }
  if (!previousWasDigit) throw new PyValueError('trailing underscore or empty');

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

