/**
 * Minimal `textwrap.wrap()` for the fixed help strings argparse renders here.
 *
 * Matches CPython for the defaults that matter (`replace_whitespace=True`,
 * `drop_whitespace=True`, `break_long_words=True`): whitespace runs collapse to
 * a single space and words are packed greedily. Hyphen splitting
 * (`break_on_hyphens`) is not needed for these strings and is left out.
 */

/** Wrap `text` to `width` columns, returning the individual lines. */
export function wrap(text, width) {
  const limit = Math.max(1, width);
  const words = text.split(/\s+/).filter((word) => word.length > 0);
  const lines = [];
  let line = '';

  for (let word of words) {
    while (word.length > limit) {
      if (line !== '') {
        lines.push(line);
        line = '';
      }
      lines.push(word.slice(0, limit));
      word = word.slice(limit);
    }
    if (line === '') line = word;
    else if (line.length + 1 + word.length <= limit) line += ` ${word}`;
    else {
      lines.push(line);
      line = word;
    }
  }
  if (line !== '') lines.push(line);
  return lines;
}

/** `textwrap.fill()` — `wrap()` joined by newlines. */
export function fill(text, width) {
  return wrap(text, width).join('\n');
}

