/**
 * `shutil.get_terminal_size()` equivalent: honour `COLUMNS` first, then the
 * real terminal width, then fall back to 80 columns (what CPython does when
 * stdout is a pipe).
 */

const FALLBACK_COLUMNS = 80;

export function getTerminalColumns() {
  const fromEnv = Number.parseInt(process.env.COLUMNS ?? '', 10);
  if (Number.isInteger(fromEnv) && fromEnv > 0) return fromEnv;
  if (process.stdout.isTTY && process.stdout.columns > 0) return process.stdout.columns;
  return FALLBACK_COLUMNS;
}

