/**
 * Port of the parts of `argparse.HelpFormatter` this CLI exercises: the usage
 * line (including its wrapping algorithm) and the options section.
 */

import { wrap } from '../py/textwrap.mjs';
import { getTerminalColumns } from '../py/terminal.mjs';

const MAX_HELP_POSITION = 24;
const INDENT = 2;

// argparse splits the usage string into wrappable chunks with this pattern:
// bracketed/parenthesised groups stay together, everything else splits on
// whitespace — which is why `--k1 K1` can break across two lines.
const PART_RE = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;

/** Width argparse formats against: terminal columns minus two. */
export function formatterWidth() {
  return getTerminalColumns() - 2;
}

/** `'--k1 K1'` style invocation used in both usage and the options list. */
function formatInvocation(action, optionString) {
  if (action.nargs === 0) return optionString;
  return `${optionString} ${action.metavar ?? action.dest.toUpperCase()}`;
}

/** `_format_action_invocation`: every option string, comma separated. */
function formatActionInvocation(action) {
  return action.optionStrings.map((opt) => formatInvocation(action, opt)).join(', ');
}

/** `_format_actions_usage` for optionals: required bare, optional bracketed. */
function formatActionsUsage(actions) {
  return actions
    .map((action) => {
      const part = formatInvocation(action, action.optionStrings[0]);
      return action.required ? part : `[${part}]`;
    })
    .filter((part) => part.length > 0)
    .join(' ');
}

/**
 * Greedy packing used by `_format_usage`. `prefix` marks the first line as
 * already carrying `usage: `, whose length replaces the hanging indent.
 */
function getLines(parts, indent, textWidth, prefix) {
  const lines = [];
  let line = [];
  let lineLen = (prefix === undefined ? indent.length : prefix.length) - 1;

  for (const part of parts) {
    if (lineLen + 1 + part.length > textWidth && line.length > 0) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLen = indent.length - 1;
    }
    line.push(part);
    lineLen += 1 + part.length;
  }
  if (line.length > 0) lines.push(indent + line.join(' '));
  if (prefix !== undefined && lines.length > 0) lines[0] = lines[0].slice(indent.length);
  return lines;
}

/** `formatter.add_usage(...)` — returns the block ending in a blank line. */
export function formatUsage(prog, actions, width) {
  const prefix = 'usage: ';
  const optionals = actions.filter((action) => action.optionStrings.length > 0);
  const positionals = actions.filter((action) => action.optionStrings.length === 0);
  const actionUsage = formatActionsUsage([...optionals, ...positionals]);
  let usage = [prog, actionUsage].filter((piece) => piece.length > 0).join(' ');

  const textWidth = width;
  if (prefix.length + usage.length > textWidth) {
    const optParts = formatActionsUsage(optionals).match(PART_RE) ?? [];
    const posParts = formatActionsUsage(positionals).match(PART_RE) ?? [];
    let lines;
    if (prefix.length + prog.length <= 0.75 * textWidth) {
      const indent = ' '.repeat(prefix.length + prog.length + 1);
      if (optParts.length > 0) {
        lines = getLines([prog, ...optParts], indent, textWidth, prefix);
        lines.push(...getLines(posParts, indent, textWidth));
      } else if (posParts.length > 0) {
        lines = getLines([prog, ...posParts], indent, textWidth, prefix);
      } else {
        lines = [prog];
      }
    } else {
      const indent = ' '.repeat(prefix.length);
      const parts = [...optParts, ...posParts];
      lines = getLines(parts, indent, textWidth, prefix);
      if (lines.length > 1) {
        lines = [];
        lines.push(...getLines(optParts, indent, textWidth));
        lines.push(...getLines(posParts, indent, textWidth));
      }
      lines = [prog, ...lines];
    }
    usage = lines.join('\n');
  }
  return `${prefix}${usage}\n\n`;
}

/** `_format_action` for one option, at the shared help column. */
function formatAction(action, helpPosition, width) {
  const helpWidth = Math.max(width - helpPosition, 11);
  const actionWidth = helpPosition - INDENT - 2;
  const invocation = formatActionInvocation(action);
  const pad = ' '.repeat(INDENT);

  let header;
  let indentFirst = 0;
  if (!action.help) {
    return `${pad}${invocation}\n`;
  }
  if (invocation.length <= actionWidth) {
    header = pad + invocation.padEnd(actionWidth) + '  ';
  } else {
    header = `${pad}${invocation}\n`;
    indentFirst = helpPosition;
  }

  const helpLines = wrap(action.help, helpWidth);
  const parts = [header];
  parts.push(`${' '.repeat(indentFirst)}${helpLines[0]}\n`);
  for (const line of helpLines.slice(1)) parts.push(`${' '.repeat(helpPosition)}${line}\n`);
  return parts.join('');
}

/** Shared help column: `min(max invocation length + indent + 2, 24)`. */
function computeHelpPosition(actions) {
  const longest = Math.max(...actions.map((a) => formatActionInvocation(a).length), 0);
  return Math.min(longest + INDENT + 2, MAX_HELP_POSITION);
}

/**
 * `formatter.format_help()`'s final clean-up: collapse runs of blank lines and
 * end with exactly one newline.
 */
function finalize(text) {
  return `${text.replace(/\n\n\n+/g, '\n\n').replace(/^\n+|\n+$/g, '')}\n`;
}

/** Full `parser.format_help()` output. */
export function formatHelp(prog, actions, groups, width) {
  let text = formatUsage(prog, actions, width);
  const helpPosition = computeHelpPosition(actions);
  for (const group of groups) {
    if (group.actions.length === 0) continue; // empty sections render as nothing
    const body = group.actions.map((a) => formatAction(a, helpPosition, width)).join('');
    text += `${group.title}:\n${body}\n`;
  }
  return finalize(text);
}

/** `parser.format_usage()` — the usage block alone. */
export function formatUsageOnly(prog, actions, width) {
  return finalize(formatUsage(prog, actions, width));
}

