/**
 * Port of `argparse.ArgumentParser` covering the surface this CLI needs:
 * long/short options, `--opt=value`, unique-prefix abbreviation with ambiguity
 * detection, `type=` conversion, required-argument checking, `-h/--help`, the
 * `--` separator, and argparse's exact error strings and exit codes.
 */

import { reprStr } from '../py/repr.mjs';
import { stdoutWrite, stderrWrite, pyExit } from '../py/stdio.mjs';
import { formatHelp, formatUsageOnly, formatterWidth } from './formatter.mjs';

const PREFIX_CHARS = '-';
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

/** Raised for per-argument problems; the parser turns it into an error exit. */
class ArgumentError extends Error {
  constructor(action, message) {
    super(message);
    this.actionName = action === null ? null : action.optionStrings.join('/');
  }

  format() {
    return this.actionName === null
      ? this.message
      : `argument ${this.actionName}: ${this.message}`;
  }
}

/** Signals that `_parse_optional` already reported a fatal parser error. */
class ParserError extends Error {
  constructor(message) {
    super(message);
    this.parserMessage = message;
  }
}

class Action {
  constructor({ optionStrings, dest, type = null, required = false, help = null, nargs, isHelp = false }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.type = type;
    this.required = required;
    this.help = help;
    this.nargs = nargs; // undefined -> exactly one value, 0 -> flag
    this.isHelp = isHelp;
  }
}

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this._actions = [];
    this._optionStringActions = Object.create(null);
    this._groups = [
      { title: 'positional arguments', actions: [] },
      { title: 'options', actions: [] },
    ];
    this.addArgument(['-h', '--help'], {
      dest: 'help',
      nargs: 0,
      isHelp: true,
      help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, options = {}) {
    const dest = options.dest ?? optionStrings[0].replace(/^-+/, '').replace(/-/g, '_');
    const action = new Action({ ...options, optionStrings, dest });
    this._actions.push(action);
    this._groups[1].actions.push(action);
    for (const optionString of optionStrings) this._optionStringActions[optionString] = action;
    return action;
  }

  get width() {
    return formatterWidth();
  }

  formatUsage() {
    return formatUsageOnly(this.prog, this._actions, this.width);
  }

  formatHelp() {
    return formatHelp(this.prog, this._actions, this._groups, this.width);
  }

  printHelp() {
    stdoutWrite(this.formatHelp());
  }

  /** `parser.error()`: usage plus message on stderr, exit status 2. */
  error(message) {
    stderrWrite(this.formatUsage());
    stderrWrite(`${this.prog}: error: ${message}\n`);
    pyExit(2);
  }

  /** `_parse_optional`: classify one argument string. */
  _parseOptional(argString) {
    if (argString === '') return null;
    if (!PREFIX_CHARS.includes(argString[0])) return null;
    if (argString in this._optionStringActions) {
      return [this._optionStringActions[argString], argString, null];
    }
    if (argString.length === 1) return null;
    if (argString.includes('=')) {
      const splitAt = argString.indexOf('=');
      const optionString = argString.slice(0, splitAt);
      const explicitArg = argString.slice(splitAt + 1);
      if (optionString in this._optionStringActions) {
        return [this._optionStringActions[optionString], optionString, explicitArg];
      }
    }

    const optionTuples = this._getOptionTuples(argString);
    if (optionTuples.length > 1) {
      const matches = optionTuples.map(([, optionString]) => optionString).join(', ');
      throw new ParserError(`ambiguous option: ${argString} could match ${matches}`);
    }
    if (optionTuples.length === 1) return optionTuples[0];

    // Looks like a negative number and no option does: treat as positional.
    if (NEGATIVE_NUMBER_RE.test(argString) && !this._hasNegativeNumberOptionals()) return null;
    if (argString.includes(' ')) return null;
    return [null, argString, null];
  }

  _hasNegativeNumberOptionals() {
    return this._actions.some((action) =>
      action.optionStrings.some((opt) => NEGATIVE_NUMBER_RE.test(opt)));
  }

  /** `_get_option_tuples`: abbreviation and concatenated-short-option matches. */
  _getOptionTuples(argString) {
    const result = [];
    const known = Object.keys(this._optionStringActions);

    if (PREFIX_CHARS.includes(argString[0]) && PREFIX_CHARS.includes(argString[1])) {
      let optionPrefix = argString;
      let explicitArg = null;
      if (argString.includes('=')) {
        const splitAt = argString.indexOf('=');
        optionPrefix = argString.slice(0, splitAt);
        explicitArg = argString.slice(splitAt + 1);
      }
      for (const optionString of known) {
        if (optionString.startsWith(optionPrefix)) {
          result.push([this._optionStringActions[optionString], optionString, explicitArg]);
        }
      }
    } else {
      const shortOptionPrefix = argString.slice(0, 2);
      const shortExplicitArg = argString.slice(2);
      for (const optionString of known) {
        if (optionString === shortOptionPrefix) {
          result.push([this._optionStringActions[optionString], optionString, shortExplicitArg]);
        } else if (optionString.startsWith(argString)) {
          result.push([this._optionStringActions[optionString], optionString, null]);
        }
      }
    }
    return result;
  }

  /** `_match_argument`: how many pattern slots this action consumes. */
  _matchArgument(action, argStringsPattern) {
    if (action.nargs === 0) return 0;
    const match = /^(-*A-*)/.exec(argStringsPattern);
    if (match === null) throw new ArgumentError(action, 'expected one argument');
    return match[1].length;
  }

  /** `_get_values` + `_get_value`: drop a leading `--`, then convert. */
  _getValues(action, argStrings) {
    const values = argStrings.slice();
    const dashDash = values.indexOf('--');
    if (dashDash !== -1) values.splice(dashDash, 1);
    const argString = values[0];
    if (action.type === null) return argString;
    try {
      return action.type(argString);
    } catch {
      throw new ArgumentError(
        action,
        `invalid ${action.typeName} value: ${reprStr(argString)}`,
      );
    }
  }

  parseArgs(argv) {
    try {
      return this._parseArgs(argv);
    } catch (err) {
      if (err instanceof ParserError) this.error(err.parserMessage);
      if (err instanceof ArgumentError) this.error(err.format());
      throw err;
    }
  }

  _parseArgs(argv) {
    const namespace = Object.create(null);
    for (const action of this._actions) {
      if (!action.isHelp) namespace[action.dest] = null;
    }

    // Classify every argument up front: 'O' option, 'A' value, '-' separator.
    const pattern = [];
    const tuples = [];
    for (let i = 0; i < argv.length; i += 1) {
      if (argv[i] === '--') {
        pattern.push('-');
        tuples.push(null);
        for (let j = i + 1; j < argv.length; j += 1) {
          pattern.push('A');
          tuples.push(null);
        }
        break;
      }
      const tuple = this._parseOptional(argv[i]);
      tuples.push(tuple);
      pattern.push(tuple === null ? 'A' : 'O');
    }
    const patternText = pattern.join('');

    const seen = new Set();
    const extras = [];
    let index = 0;

    const takeAction = (action, argStrings) => {
      seen.add(action);
      if (action.isHelp) {
        this.printHelp();
        pyExit(0);
      }
      namespace[action.dest] = this._getValues(action, argStrings);
    };

    while (index < argv.length) {
      if (pattern[index] !== 'O') {
        extras.push(argv[index]);
        index += 1;
        continue;
      }

      // `consume_optional`
      let [action, optionString, explicitArg] = tuples[index];
      const actionTuples = [];
      let stop = index;
      for (;;) {
        if (action === null) {
          extras.push(optionString);
          stop = index + 1;
          break;
        }
        if (explicitArg !== null) {
          const argCount = this._matchArgument(action, 'A');
          if (argCount === 0 && !PREFIX_CHARS.includes(optionString[1]) && explicitArg !== '') {
            // `-xy` where `-x` is a flag: retry `-y` as another short option.
            actionTuples.push([action, []]);
            const char = optionString[0];
            const nextOptionString = char + explicitArg[0];
            const nextExplicitArg = explicitArg.slice(1) === '' ? null : explicitArg.slice(1);
            if (nextOptionString in this._optionStringActions) {
              action = this._optionStringActions[nextOptionString];
              optionString = nextOptionString;
              explicitArg = nextExplicitArg;
              continue;
            }
            extras.push(char + explicitArg);
            stop = index + 1;
            break;
          }
          if (argCount === 1) {
            actionTuples.push([action, [explicitArg]]);
            stop = index + 1;
            break;
          }
          throw new ArgumentError(action, `ignored explicit argument ${reprStr(explicitArg)}`);
        }
        const start = index + 1;
        const argCount = this._matchArgument(action, patternText.slice(start));
        stop = start + argCount;
        actionTuples.push([action, argv.slice(start, stop)]);
        break;
      }
      for (const [act, args] of actionTuples) takeAction(act, args);
      index = stop;
    }

    const missing = this._actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.optionStrings[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

