/**
 * Insertion-ordered dictionary with Python `dict` semantics, built from a plain
 * null-prototype lookup table plus a slot array:
 *
 *   - re-assigning an existing key keeps its original position
 *   - deleting then re-inserting a key moves it to the end
 *   - `str` and arbitrary-precision `int` keys never collide
 *
 * Deleted slots are left as holes and compacted once they dominate the array.
 */

/** Stable lookup token for a key, keeping `str` and `int` domains separate. */
function hashKey(key) {
  const kind = typeof key;
  if (kind === 'string') return `s:${key}`;
  if (kind === 'bigint') return `i:${key.toString()}`;
  if (kind === 'number') return Number.isInteger(key) ? `i:${key}` : `f:${key}`;
  if (kind === 'boolean') return `i:${key ? 1 : 0}`;
  if (key === null) return 'n:';
  throw new TypeError(`unhashable type: ${kind}`);
}

/** True when two keys/values are equal under the same rules as `hashKey`. */
export function pyEquals(left, right) {
  return hashKey(left) === hashKey(right);
}

export class PyDict {
  #slots = []; // [key, value] pairs in insertion order, or null for holes
  #index = Object.create(null); // hashKey -> slot position
  #count = 0;

  get size() {
    return this.#count;
  }

  has(key) {
    return hashKey(key) in this.#index;
  }

  /** Value for `key`, or `undefined` when absent (callers raise KeyError). */
  get(key) {
    const position = this.#index[hashKey(key)];
    return position === undefined ? undefined : this.#slots[position][1];
  }

  set(key, value) {
    const token = hashKey(key);
    const position = this.#index[token];
    if (position === undefined) {
      this.#index[token] = this.#slots.length;
      this.#slots.push([key, value]);
      this.#count += 1;
    } else {
      this.#slots[position] = [key, value];
    }
  }

  delete(key) {
    const token = hashKey(key);
    const position = this.#index[token];
    if (position === undefined) return false;
    delete this.#index[token];
    this.#slots[position] = null;
    this.#count -= 1;
    if (this.#slots.length > 8 && this.#count * 2 < this.#slots.length) this.#compact();
    return true;
  }

  clear() {
    this.#slots = [];
    this.#index = Object.create(null);
    this.#count = 0;
  }

  #compact() {
    const live = this.#slots.filter((slot) => slot !== null);
    this.#slots = live;
    this.#index = Object.create(null);
    for (let i = 0; i < live.length; i += 1) this.#index[hashKey(live[i][0])] = i;
  }

  /** Ordered `[key, value]` pairs, like `dict.items()`. */
  entries() {
    return this.#slots.filter((slot) => slot !== null).map((slot) => [slot[0], slot[1]]);
  }

  keys() {
    return this.entries().map(([key]) => key);
  }

  values() {
    return this.entries().map(([, value]) => value);
  }
}

