/**
 * Exception types raised by bidict, plus the builtin `KeyError`, carrying the
 * information CPython's traceback machinery prints:
 *   - `pyName`   the fully qualified type name (`bidict.ValueDuplicationError`)
 *   - `pyValue`  the single exception argument
 *   - `pyFrames` library frames leading to the raise
 */

import { pyRepr, pyStr, reprTuple } from '../py/repr.mjs';

/** Base for exceptions that render like CPython's in a traceback. */
export class PyException extends Error {
  constructor(pyName, pyValue, pyFrames = []) {
    super(pyName);
    this.pyName = pyName;
    this.pyValue = pyValue;
    this.pyFrames = pyFrames;
  }

  /** `str(exc)` — for a single argument, `str(args[0])`. */
  pyMessage() {
    return pyStr(this.pyValue);
  }

  /** The final `Type: message` line of a traceback. */
  exceptionLine() {
    return `${this.pyName}: ${this.pyMessage()}`;
  }
}

/** `KeyError` renders its argument with `repr()` rather than `str()`. */
export class PyKeyError extends PyException {
  constructor(key, pyFrames = []) {
    super('KeyError', key, pyFrames);
  }

  pyMessage() {
    return pyRepr(this.pyValue);
  }
}

export class DuplicationError extends PyException {}

/** Inserting a new key whose value already belongs to another key. */
export class ValueDuplicationError extends DuplicationError {
  constructor(value, pyFrames = []) {
    super('bidict.ValueDuplicationError', value, pyFrames);
  }
}

