export class KeyAndValueDuplicationError extends DuplicationError {
  constructor(key, value, pyFrames = []) {
    super('bidict.KeyAndValueDuplicationError', [key, value], pyFrames);
  }

  pyMessage() {
    return reprTuple(this.pyValue);
  }
}

