/**
 * Frame descriptors for the bidict internals that appear in a traceback.
 *
 * The library is only observable as a black box here, so these mirror the frame
 * chains the reference build prints — the internal source lines themselves are
 * not shown, only `File "...", line N, in name`.
 */

const frame = (file, line, name) => ({ file, line, name });

/** `b[key] = value` raising during de-duplication. */
export function setItemFrames(dedupLine) {
  return [
    frame('bidict/_bidict.py', 80, '__setitem__'),
    frame('bidict/_bidict.py', 106, 'put'),
    frame('bidict/_base.py', 454, '_update'),
    frame('bidict/_base.py', dedupLine, '_dedup'),
  ];
}

/** Line inside `_dedup` that raises each duplication error. */
export const DEDUP_KEY_AND_VALUE_LINE = 333;
export const DEDUP_VALUE_LINE = 347;

/** `b[key]` / `b.inv[key]` raising KeyError. */
export function getItemFrames() {
  return [frame('bidict/_base.py', 524, '__getitem__')];
