/**
 * `bidict.bidict` — a mutable, insertion-ordered one-to-one mapping.
 *
 * Both directions are kept in sync, so values must stay unique. Assignment
 * follows bidict's default `ON_DUP` policy, which is what the reference
 * behaviour shows:
 *
 *   | key exists | value exists | result                              |
 *   |------------|--------------|-------------------------------------|
 *   | no         | no           | insert at the end                   |
 *   | yes        | no           | replace the value, keep the position|
 *   | no         | yes          | ValueDuplicationError               |
 *   | yes        | yes, same    | no-op (the pair is already present) |
 *   | yes        | yes, other   | KeyAndValueDuplicationError         |
 */

import { reprDict } from '../py/repr.mjs';
import { PyDict, pyEquals } from './pydict.mjs';
import {
  KeyAndValueDuplicationError,
  PyKeyError,
  ValueDuplicationError,
} from './exceptions.mjs';
import {
  DEDUP_KEY_AND_VALUE_LINE,
  DEDUP_VALUE_LINE,
  getItemFrames,
  setItemFrames,
} from './frames.mjs';

export class Bidict {
  #fwd;
  #bwd;
  #inverse = null;

  /** Internal use: an inverse twin reuses the same two dicts, swapped. */
  constructor(fwd = new PyDict(), bwd = new PyDict()) {
    this.#fwd = fwd;
    this.#bwd = bwd;
  }

  /** `b.inv` — a live view whose keys are this mapping's values. */
  get inv() {
    if (this.#inverse === null) {
      const twin = new Bidict(this.#bwd, this.#fwd);
      twin.#inverse = this;
      this.#inverse = twin;
    }
    return this.#inverse;
  }

  /** `b.inverse` — the documented alias for `b.inv`. */
  get inverse() {
    return this.inv;
  }

  get size() {
    return this.#fwd.size;
  }

  /** `key in b` */
  contains(key) {
    return this.#fwd.has(key);
  }

  /** `b[key]` */
  getItem(key) {
    if (!this.#fwd.has(key)) throw new PyKeyError(key, getItemFrames());
    return this.#fwd.get(key);
  }

  /** `b.get(key, default)` */
  get(key, fallback = null) {
    return this.#fwd.has(key) ? this.#fwd.get(key) : fallback;
  }

  /** `b[key] = value` */
  setItem(key, value) {
    const hasKey = this.#fwd.has(key);
    const hasValue = this.#bwd.has(value);

    if (hasKey && hasValue) {
      if (pyEquals(this.#fwd.get(key), value)) return; // identical pair: no-op
      throw new KeyAndValueDuplicationError(
        key,
        value,
        setItemFrames(DEDUP_KEY_AND_VALUE_LINE),
      );
    }
    if (hasValue) {
      throw new ValueDuplicationError(value, setItemFrames(DEDUP_VALUE_LINE));
    }
    if (hasKey) this.#bwd.delete(this.#fwd.get(key));
    this.#fwd.set(key, value);
    this.#bwd.set(value, key);
  }

  /** `del b[key]` */
  delItem(key) {
    if (!this.#fwd.has(key)) throw new PyKeyError(key, getItemFrames());
    const value = this.#fwd.get(key);
    this.#fwd.delete(key);
    this.#bwd.delete(value);
  }

  /** `b.items()` in insertion order. */
  entries() {
    return this.#fwd.entries();
  }

  keys() {
    return this.#fwd.keys();
  }

  values() {
    return this.#fwd.values();
  }

  /** `repr(b)` — an empty bidict renders without a dict argument. */
  toString() {
    if (this.#fwd.size === 0) return 'bidict()';
    return `bidict(${reprDict(this.#fwd.entries())})`;
  }
}

/** Mirrors `bidict()` / `bidict(pairs)`. */
export function bidict(pairs = []) {
  const result = new Bidict();
  for (const [key, value] of pairs) result.setItem(key, value);
  return result;
}

