/**
 * Renders an uncaught exception the way CPython does: the traceback header, one
 * block per frame (innermost last), then the `Type: message` line — all on
 * stderr, followed by exit status 1.
 */

import { stderrWrite, pyExit } from './stdio.mjs';

/**
 * @param {{file: string, line: number, name: string, source?: string[]}[]} frames
 *        Outermost first. `source` holds display lines already indented.
 * @param {{exceptionLine: () => string}} exc
 */
export function formatTraceback(frames, exc) {
  let out = 'Traceback (most recent call last):\n';
  for (const frame of frames) {
    out += `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
    for (const line of frame.source ?? []) out += `${line}\n`;
  }
  return `${out}${exc.exceptionLine()}\n`;
}

/** Print the traceback and terminate with CPython's unhandled-exception status. */
export function abortWithTraceback(frames, exc) {
  stderrWrite(formatTraceback(frames, exc));
  pyExit(1);
}

