/**
 * Node.js port of test8.py.
 *
 *   import argparse
 *   from bidict import bidict
 *   ... build a bidict from three CLI pairs, read it both ways, then update one
 *
 * Run: node test8.mjs --k1 i --v1 55 --k2 c --v2 95 --k3 t --v3 92
 */

import { ArgumentParser, intType, strType } from './lib/argparse/index.mjs';
import { bidict } from './lib/bidict/index.mjs';
import { PyException } from './lib/bidict/exceptions.mjs';
import { pyPrint, pyExit } from './lib/py/stdio.mjs';
import { pyStr } from './lib/py/repr.mjs';
import { abortWithTraceback } from './lib/py/traceback.mjs';

// The reference build reports itself under this name in usage and tracebacks.
const PROG = 'test8_executable';
const SOURCE_FILE = 'test8.py';

/**
 * Statements that can raise, with the source line and caret anchors CPython
 * prints for them. Keyed by the line number in test8.py.
 */
const site = (line, text, anchor) => ({
  file: SOURCE_FILE,
  line,
  name: '<module>',
  source: [`    ${text}`, `    ${anchor}`],
});

const SITES = {
  setK1: site(15, 'b[args.k1] = args.v1', '~^^^^^^^^^'),
  setK2: site(16, 'b[args.k2] = args.v2', '~^^^^^^^^^'),
  setK3: site(17, 'b[args.k3] = args.v3', '~^^^^^^^^^'),
  getK1: site(21, 'print(b[args.k1])', '      ~^^^^^^^^^'),
  getInvV2: site(22, 'print(b.inv[args.v2])', '      ~~~~~^^^^^^^^^'),
  getInvV3: site(23, 'print(b.inv[args.v3])', '      ~~~~~^^^^^^^^^'),
  updateK1: site(26, 'b[args.k1] = 999', '~^^^^^^^^^'),
};

/** Run one statement; an escaping Python exception ends the process. */
function at(where, statement) {
  try {
    return statement();
  } catch (err) {
    if (err instanceof PyException) abortWithTraceback([where, ...err.pyFrames], err);
    throw err;
  }
}

function buildParser() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--k1'], { type: strType, required: true });
  parser.addArgument(['--v1'], { type: intType, required: true });
  parser.addArgument(['--k2'], { type: strType, required: true });
  parser.addArgument(['--v2'], { type: intType, required: true });
  parser.addArgument(['--k3'], { type: strType, required: true });
  parser.addArgument(['--v3'], { type: intType, required: true });
  return parser;
}

function main() {
  const args = buildParser().parseArgs(process.argv.slice(2));

  // 复杂的多步操作
  const b = bidict();
  at(SITES.setK1, () => b.setItem(args.k1, args.v1));
  at(SITES.setK2, () => b.setItem(args.k2, args.v2));
  at(SITES.setK3, () => b.setItem(args.k3, args.v3));
  pyPrint(b.toString());

  // 通过不同方式访问
  pyPrint(pyStr(at(SITES.getK1, () => b.getItem(args.k1))));
  pyPrint(pyStr(at(SITES.getInvV2, () => b.inv.getItem(args.v2))));
  pyPrint(pyStr(at(SITES.getInvV3, () => b.inv.getItem(args.v3))));

  // 更新一个值
  at(SITES.updateK1, () => b.setItem(args.k1, 999n));
  pyPrint(b.toString());
}

main();
pyExit(0);

