_matchArgument(action, argStringsPattern) {
  if (action.nargs === 0) return 0;
  // `_get_nargs_pattern`: one value, and for an optional the surrounding
  // `-*` is stripped — a `--` separator may not be swallowed as its value.
  let nargsPattern = '(-*A-*)';
  if (action.optionStrings.length > 0) {
    nargsPattern = nargsPattern.replaceAll('-*', '').replaceAll('-', '');
