/**
 * Port of the parts of `argparse.HelpFormatter` this CLI exercises: the usage
 * line (including its wrapping algorithm) and the options section.
 */

import { wrap } from '../py/textwrap.mjs';
import { getTerminalColumns } from '../py/terminal.mjs';

const MAX_HELP_POSITION = 24;
const INDENT = 2;

// argparse splits the usage string into wrappable chunks with this pattern:
// bracketed/parenthesised groups stay together, everything else splits on
// whitespace — which is why `--k1 K1` can break across two lines.
const PART_RE = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;

/** Width argparse formats against: terminal columns minus two. */
export function formatterWidth() {
  return getTerminalColumns() - 2;
}

/** `'--k1 K1'` style invocation used in both usage and the options list. */
function formatInvocation(action, optionString) {
  if (action.nargs === 0) return optionString;
  return `${optionString} ${action.metavar ?? action.dest.toUpperCase()}`;
}

/** `_format_action_invocation`: every option string, comma separated. */
function formatActionInvocation(action) {
  return action.optionStrings.map((opt) => formatInvocation(action, opt)).join(', ');
}

/** `_format_actions_usage` for optionals: required bare, optional bracketed. */
function formatActionsUsage(actions) {
  return actions
    .map((action) => {
      const part = formatInvocation(action, action.optionStrings[0]);
      return action.required ? part : `[${part}]`;
    })
    .filter((part) => part.length > 0)
    .join(' ');
}

/**
 * Greedy packing used by `_format_usage`. `prefix` marks the first line as
 * already carrying `usage: `, whose length replaces the hanging indent.
 */
function getLines(parts, indent, textWidth, prefix) {
  const lines = [];
  let line = [];
  let lineLen = (prefix === undefined ? indent.length : prefix.length) - 1;

  for (const part of parts) {
    if (lineLen + 1 + part.length > textWidth && line.length > 0) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLen = indent.length - 1;
    }
    line.push(part);
    lineLen += 1 + part.length;
  }
  if (line.length > 0) lines.push(indent + line.join(' '));
  if (prefix !== undefined && lines.length > 0) lines[0] = lines[0].slice(indent.length);
  return lines;
}

/** `formatter.add_usage(...)` — returns the block ending in a blank line. */
export function formatUsage(prog, actions, width) {
  const prefix = 'usage: ';
