/**
 * `linecache` equivalent: resolves the source line a traceback frame refers to.
 *
 * CPython records a *relative* filename for the frozen script, so whether a
 * traceback shows source text depends on the process's working directory — the
 * line appears only when e.g. `test8.py` sits next to where the program is run.
 * Missing or unreadable files simply yield no line, exactly as `linecache` does.
 */

import { readFileSync } from 'node:fs';

const cache = Object.create(null);

function getLines(filename) {
  if (filename in cache) return cache[filename];
  let lines = [];
  try {
    const text = readFileSync(filename, 'utf8');
    // Keep line endings, like `readlines()`, so offsets match CPython's.
    lines = text.match(/[^\n]*\n|[^\n]+/g) ?? [];
  } catch {
    lines = []; // no such file / not readable: linecache returns []
  }
  cache[filename] = lines;
  return lines;
}

/** `linecache.getline(filename, lineno)`; `''` when unavailable. */
export function getLine(filename, lineno) {
  const lines = getLines(filename);
  if (lineno < 1 || lineno > lines.length) return '';
  return lines[lineno - 1];
}

