/**
 * Renders an uncaught exception the way CPython 3.11+ does: the traceback
 * header, one block per frame (outermost first), then the `Type: message` line
 * on stderr, followed by exit status 1.
 *
 * A frame block is the `File "...", line N, in name` header plus — when the
 * source file can be located — the stripped source line and the `~^^^` anchor
 * line derived from the frame's recorded column range.
 */

import { getLine } from './linecache.mjs';
import { stderrWrite, pyExit } from './stdio.mjs';

/** `_byte_offset_to_character_offset`: byte offset -> code point offset. */
function byteOffsetToCharOffset(line, byteOffset) {
  const bytes = Buffer.from(line, 'utf8');
  const decoded = bytes.subarray(0, Math.max(0, byteOffset)).toString('utf8');
  return Array.from(decoded).length;
}

/**
 * `_extract_caret_anchors_from_line_segment` restricted to subscripts, the only
 * expression shape that raises at the call sites this program has. CPython
 * parses the segment and anchors `value[index]` as `~` under `value` and `^`
 * under `[index]`; a segment that is not such an expression yields no anchors.
 */
function extractCaretAnchors(segment) {
  const match = /^([A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*)(\[[^[\]]*\])$/.exec(segment);
  if (match === null) return null;
  return { leftEnd: match[1].length, rightStart: match[1].length + match[2].length };
}

/** The source and anchor lines for one frame, or `''` when unavailable. */
function formatFrameSource(frame) {
  const rawLine = getLine(frame.file, frame.line);
  if (rawLine.trim() === '') return '';

  const chars = Array.from(rawLine);
  const strippedLine = rawLine.trim();
  const strippedCharacters = chars.length - Array.from(rawLine.replace(/^\s+/, '')).length;
  let out = `    ${strippedLine}\n`;
  if (frame.colno === undefined || frame.endColno === undefined) return out;

  const startOffset = byteOffsetToCharOffset(rawLine, frame.colno);
  const endOffset = byteOffsetToCharOffset(rawLine, frame.endColno);
  const segment = chars.slice(startOffset, endOffset).join('');
  const anchors = extractCaretAnchors(segment);

  // CPython hides anchors that would span the whole displayed line.
  const spansWholeLine = endOffset - startOffset >= Array.from(strippedLine).length;
  if (spansWholeLine && !(anchors && anchors.rightStart < anchors.leftEnd)) return out;

  out += `    ${' '.repeat(Math.max(0, startOffset - strippedCharacters))}`;
  if (anchors) {
    out += '~'.repeat(anchors.leftEnd);
    out += '^'.repeat(anchors.rightStart - anchors.leftEnd);
    out += '~'.repeat(Math.max(0, endOffset - startOffset - anchors.rightStart));
  } else {
    out += '^'.repeat(endOffset - startOffset);
  }
  return `${out}\n`;
}

/**
 * @param {{file: string, line: number, name: string, colno?: number, endColno?: number}[]} frames
 *        Outermost first.
 * @param {{exceptionLine: () => string}} exc
 */
export function formatTraceback(frames, exc) {
  let out = 'Traceback (most recent call last):\n';
  for (const frame of frames) {
    out += `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
    out += formatFrameSource(frame);
  }
  return `${out}${exc.exceptionLine()}\n`;
}

/** Print the traceback and terminate with CPython's unhandled-exception status. */
export function abortWithTraceback(frames, exc) {
  stderrWrite(formatTraceback(frames, exc));
  pyExit(1);
}

